#include <cstddef>
#include <vector>

// keep может бросить, но не меняет values и не хранит ссылки.
// Внешние эффекты keep не откатываются; стандартный аллокатор.
template<class Pred>
void Filter(std::vector<int>& values, Pred keep) {
  std::size_t out = 0;
  for (int value : values) {
    if (keep(value)) {
      values[out++] = value;
    }
  }
  values.resize(out);
}
